const MAX_CHARS = 6000;
const MIN_WORDS = 5;
const keepAnyway = /@|www\.|\+\d|\d{4} /;
const linkPattern = new RegExp('\\[(https?:|data:|tel:|mailto:|/)[^\\]]*\\]', 'g');

for (const item of $input.all()) {
  let text = item.json.pageText || '';
  text = text.replace(linkPattern, ' ');
  text = text.replace(/[ \t]+/g, ' ');

  const seen = new Set();
  const kept = [];

  for (let line of text.split('\n')) {
    line = line.replace(/^[*\s]+/, '').trim();
    if (!line || seen.has(line)) continue;
    seen.add(line);
    const words = line.split(' ').length;
    if (words >= MIN_WORDS || keepAnyway.test(line)) kept.push(line);
  }

  const clean = kept.join('\n');
  item.json.pageTextClean = clean.slice(0, MAX_CHARS);
  item.json.pageTextChars = clean.length;
  item.json.pageTextTruncated = clean.length > MAX_CHARS;
  item.json.pageTextRawChars = text.length;
}

return $input.all();

