const form = $('On form submission').first().json;

// Rate card. Update from the pricing page when models or rates change.
const RATES = {
  model: 'claude-sonnet-5',
  usd_per_mtok_in: 2.00,
  usd_per_mtok_out: 10.00,
  usd_per_web_search: 0.01,
};

const submittedAt = form.submittedAt ? new Date(form.submittedAt).getTime() : null;

const normalize = (u) => String(u).trim().toLowerCase().replace(/\/+$/, '');
const tidy = (arr) => [...new Set((arr || []).map(normalize))].sort();
const canon = (v) => (v ? String(v).toUpperCase().replace(/[^A-Z0-9]/g, '') : null);
const list = (v) => (Array.isArray(v) && v.length ? v.join('; ') : null);

let companyKey = null;
try {
  companyKey = $('Normalize Company Key').first().json.company_key;
} catch (e) {
  companyKey = null;
}

function extractText(json) {
  if (typeof json.text === 'string') return json.text;
  const content = json.content || (json.message && json.message.content);
  if (Array.isArray(content)) {
    return content.filter(b => b.type === 'text').map(b => b.text).join('\n').trim();
  }
  if (typeof content === 'string') return content;
  return '';
}

function extractJson(s) {
  const tick = String.fromCharCode(96);
  const fence = tick + tick + tick;
  const fencedRe = new RegExp(fence + '(?:json)?\\s*([\\s\\S]*?)' + fence, 'i');
  const fenced = s.match(fencedRe);
  if (fenced) return fenced[1].trim();

  const start = s.indexOf('{');
  const end = s.lastIndexOf('}');
  if (start !== -1 && end > start) return s.slice(start, end + 1);
  return s.trim();
}

function retrievedUrls(json) {
  const urls = [];
  for (const b of (json.content || [])) {
    if (b.type === 'web_search_tool_result' && Array.isArray(b.content)) {
      for (const r of b.content) {
        if (r.url) urls.push(r.url);
      }
    }
  }
  return urls;
}

const out = [];

for (const item of $input.all()) {
  const full = extractText(item.json).trim();
  const candidate = extractJson(full);
  const stopReason = item.json.stop_reason || null;

  const usage = item.json.usage || {};
  const inTok = usage.input_tokens || 0;
  const outTok = usage.output_tokens || 0;
  const searches = (usage.server_tool_use && usage.server_tool_use.web_search_requests) || 0;

  const costUsd = (inTok / 1e6) * RATES.usd_per_mtok_in
                + (outTok / 1e6) * RATES.usd_per_mtok_out
                + searches * RATES.usd_per_web_search;

  const durationSec = submittedAt
    ? Math.round((Date.now() - submittedAt) / 100) / 10
    : null;

  let fetchedUrl = null;
  try {
    const cleaned = $('Clean page text').first().json;
    if (cleaned && cleaned.pageTextChars > 0 && form['Website']) {
      fetchedUrl = normalize(form['Website']);
    }
  } catch (e) {
    fetchedUrl = null;
  }

  const retrieved = tidy(retrievedUrls(item.json).concat(fetchedUrl ? [fetchedUrl] : []));

  const base = {
    company_key: companyKey,
    company: form['Company Name'],
    website: form['Website'] || null,
    researched_at: new Date().toISOString(),
    model: RATES.model,
    input_tokens: inTok,
    output_tokens: outTok,
    web_searches: searches,
    cost_usd_est: Number(costUsd.toFixed(4)),
    duration_sec: durationSec,
  };

  let parsed = null;
  let parseError = null;

  try {
    parsed = JSON.parse(candidate);
  } catch (e) {
    const prefix = stopReason === 'max_tokens' ? 'response truncated at token limit: ' : '';
    parseError = prefix + e.message;
  }

  if (!parsed) {
    out.push({ json: {
      ...base,
      status: 'parse_error',
      parse_error: parseError,
      stop_reason: stopReason,
      raw_response: full.slice(0, 1000),
      sources_retrieved: retrieved.join('; ') || null,
    }});
    continue;
  }

  const contact = parsed.contact || {};
  const claimed = tidy(parsed.sources);
  const unverified = claimed.filter(u => !retrieved.includes(u));

  out.push({ json: {
    ...base,
    status: 'ok',
    stop_reason: stopReason,
    what_they_do: parsed.what_they_do || null,
    trade_or_supplier: parsed.trade_or_supplier || null,
    services: list(parsed.services),
    location: parsed.location || null,
    size_signals: parsed.size_signals || null,
    named_projects_or_clients: list(parsed.named_projects_or_clients),
    phone: contact.phone || null,
    email: contact.email || null,
    registration_number: parsed.registration_number || null,
    registration_number_key: canon(parsed.registration_number),
    tax_number: parsed.tax_number || null,
    tax_number_key: canon(parsed.tax_number),
    identity_source: parsed.identity_source || null,
    research_status: parsed.research_status || null,
    research_notes: parsed.research_notes || null,
    sources: claimed.join('; ') || null,
    sources_retrieved: retrieved.join('; ') || null,
    sources_unverified: unverified.join('; ') || null,
  }});
}

return out;

return [{
  json: {
    pageTextClean: '',
    pageTextChars: 0,
    pageTextTruncated: false,
    pageTextRawChars: 0,
    fetch_failed: true,
  }
}];

const items = [];
for (const item of $input.all()) {
  const raw = String(item.json['Company Name'] || '');
  const key = raw
    .normalize('NFD')
    .replace(/\p{Diacritic}/gu, '')
    .toLowerCase()
    .replace(/\b(kft|bt|zrt|nyrt|kkt|ev|ltd|llc|inc|gmbh)\b\.?/g, '')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim()
    .replace(/\s+/g, '-');

  items.push({ json: { ...item.json, company_key: key } });
}
return items;

const MAX_AGE_DAYS = 30;
const TZ = 'Europe/Budapest';

const form = $('On form submission').first().json;
const key = $('Normalize Company Key').first().json.company_key;
const force = String(form['Re-research'] || '').toLowerCase() === 'yes';

// only a successful run counts as research already done, so an error row
// never blocks a retry
const rows = $input.all()
  .map(i => i.json || {})
  .filter(r => r.company_key && String(r.status).toLowerCase() === 'ok');

rows.sort((a, b) => new Date(b.researched_at) - new Date(a.researched_at));
const existing = rows[0] || null;

const last = existing && existing.researched_at ? new Date(existing.researched_at) : null;
const ageMs = last ? Date.now() - last.getTime() : null;
const ageDays = ageMs === null ? null : ageMs / 86400000;
const stale = ageDays !== null && ageDays > MAX_AGE_DAYS;

const lastLocal = last
  ? DateTime.fromJSDate(last).setZone(TZ).toFormat('yyyy-LL-dd HH:mm')
  : null;

let ageText = null;
if (ageMs !== null) {
  const hours = ageMs / 3600000;
  if (hours < 1) {
    ageText = Math.max(1, Math.round(ageMs / 60000)) + ' minutes ago';
  } else if (hours < 48) {
    ageText = Math.round(hours) + ' hours ago';
  } else {
    ageText = Math.round(ageDays) + ' days ago';
  }
}

let reason;
if (!existing) {
  reason = 'no successful research on file';
} else if (force) {
  reason = 'forced re-research, last done ' + ageText;
} else if (stale) {
  reason = 'past the ' + MAX_AGE_DAYS + ' day freshness window, last done ' + ageText;
} else {
  reason = 'skipped, researched ' + ageText;
}

return [{ json: {
  company_key: key,
  should_research: (!existing) || force || stale,
  last_researched_at: existing ? existing.researched_at : null,
  last_researched_local: lastLocal,
  age_days: ageDays === null ? null : Math.round(ageDays * 10) / 10,
  age_text: ageText,
  decision_reason: reason,
}}];

const form = $('On form submission').first().json;

let companyKey = null;
try {
  companyKey = $('Normalize Company Key').first().json.company_key;
} catch (e) {
  companyKey = null;
}

const err = $input.first().json || {};
const rawErr = err.error;
const message =
  (rawErr && typeof rawErr === 'object' && rawErr.message) ? rawErr.message :
  (typeof rawErr === 'string' && rawErr) ? rawErr :
  err.message || 'Claude API call failed after retry';

const submitted = form.submittedAt ? new Date(form.submittedAt).getTime() : null;

return [{ json: {
  company_key: companyKey,
  company: form['Company Name'],
  website: form['Website'] || null,
  researched_at: new Date().toISOString(),
  model: 'claude-sonnet-5',
  status: 'api_error',
  error_message: String(message).slice(0, 500),
  input_tokens: 0,
  output_tokens: 0,
  web_searches: 0,
  cost_usd_est: 0,
  duration_sec: submitted ? Math.round((Date.now() - submitted) / 100) / 10 : null,
}}];;
